$rows=find_by_sql("SELECT a.*,(SELECT e.Aplica FROM ti_amenazas_evaluaciones e WHERE e.IdAmenaza=a.IdAmenaza ORDER BY e.IdEvaluacion DESC LIMIT 1) Aplica,(SELECT e.Estado FROM ti_amenazas_evaluaciones e WHERE e.IdAmenaza=a.IdAmenaza ORDER BY e.IdEvaluacion DESC LIMIT 1) EstadoEval,(SELECT e.Prioridad FROM ti_amenazas_evaluaciones e WHERE e.IdAmenaza=a.IdAmenaza ORDER BY e.IdEvaluacion DESC LIMIT 1) Prioridad FROM ti_amenazas a ORDER BY COALESCE(a.FechaPublicacion,'1900-01-01') DESC,a.IdAmenaza DESC");
$total=count($rows);$pending=0;$applicable=0;$kev=0;foreach($rows as $r){if(!$r['EstadoEval'])$pending++;if($r['Aplica']==='SI')$applicable++;if((int)$r['ExplotacionConocida'])$kev++;}
